Lemma fire_1RB0RC_1LC1RA_1RD1LB_0LC0RD : forall t, ~ In t pins_1RB0RC_1LC1RA_1RD1LB_0LC0RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
