    intros p1 j1 E1.
    exact (firex_1RB0RC_1LC1RA_1RD1LB_0LC0RD [SWinR 2; SCycL 2 0; SWin 3] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RC_1LC1RA_1RD1LB_0LC0RD [] (StC, S0) ltac:(vm_compute; reflexivity)
