    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RC_1LC1RA_1RD1LB_0LC0RD [SWinR 2; SCycL 2 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
