    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RC_1RC1LB_1LA1RD_0LB0RC [SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
