    apply (lap_of_run tm Cc true true cho_1RB0RD_0LB1RC_1LC1RA_1LB0RD B0_1RB0RD_0LB1RC_1LC1RA_1LB0RD B1_1RB0RD_0LB1RC_1LC1RA_1LB0RD 2 8 p j' [] []).
