  - intros t Ht p _. apply fire_1RB0RD_0LB1RC_1LC1RA_1LB0RD. exact Ht.
  - exact wit_1RB0RD_0LB1RC_1LC1RA_1LB0RD.
  - apply qcleb_QC_16. reflexivity.
