(** board for 1RB0RD_0RC1RA_1LB0LC_1LC0RD (emit_lapcert.py --qh) *)
Module B_QC_16_024.
Import BBB4.BBB4_Statement BBB4.CTape BBB4.Mirror BBB4.Counters.WTape BBB4.Counters.LapGlue BBB4.Counters.LapGlueQH BBB4.Counters.LapGlueAbs BBB4.Counters.MonoCounter BBB4.Counters.JpCounter BBB4.Counters.KpCounter BBB4.Counters.LapCertGlue BBB4.Census.TNF_QH BBB4.Checkers.LapDecider BBB4.BBBT4_Statement BBB4.Checkers.WrapTr BBB4.Checkers.IRules.AnchorVisitsTr BBB4.Counters.LapGlueTr BBB4.CensusTr.TNF_QHTr BBB4.ClosureTr BBB4.Counters.LapGlueQHTr BBB4.CensusTr.TNF_QHTr BBB4.CensusTr.QHConveyorTr.
Import ListNotations.

Definition mk_1RB0RD_0RC1RA_1LB0LC_1LC0RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB0RD_0RC1RA_1LB0LC_1LC0RD.

(** 1RB0RD_0RC1RA_1LB0LC_1LC0RD *)
(** 1RB0RD_0RC1RA_1LB0LC_1LC0RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RD_0RC1RA_1LB0LC_1LC0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S1 DL StB | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DR StD end.

(** Its mirror 1LB0LD_0LC1LA_1RB0RC_1RC0LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB0RD_0RC1RA_1LB0LC_1LC0RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S0 DL StD
  | StB, S0 => mk S0 DL StC | StB, S1 => mk S1 DL StA
  | StC, S0 => mk S1 DR StB | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S0 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB0RD_0RC1RA_1LB0LC_1LC0RD : list Instr := [(StA, S0)].
Definition tmw_1RB0RD_0RC1RA_1LB0LC_1LC0RD : TM := tm_wrap_trs tmm_1RB0RD_0RC1RA_1LB0LC_1LC0RD pins_1RB0RD_0RC1RA_1LB0LC_1LC0RD.
Local Notation tm := tmw_1RB0RD_0RC1RA_1LB0LC_1LC0RD.

Lemma mirror_ok_1RB0RD_0RC1RA_1LB0LC_1LC0RD : mirror_tm tm_1RB0RD_0RC1RA_1LB0LC_1LC0RD = tmm_1RB0RD_0RC1RA_1LB0LC_1LC0RD.
Proof.
  apply functional_extensionality; intro q;
