Lemma fireo_1RB0RD_0RC1RA_1LB0LC_1LC0RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_0RC1RA_1LB0LC_1LC0RD = Some t ->
