(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RD_1LC0LB_0RB1RA_1LB0RD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0RD_1LC0LB_0RB1RA_1LB0RD /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0RD_1LC0LB_0RB1RA_1LB0RD = Cc (Pos.succ p).
