Lemma gp_1RB0RD_1LC0LB_0RB1RA_1LB0RD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0RD_1LC0LB_0RB1RA_1LB0RD /\
