    rewrite (srun_sound tm false true chp_1RB0RD_1LC0LB_0RB1RA_1LB0RD P0_1RB0RD_1LC0LB_0RB1RA_1LB0RD P1_1RB0RD_1LC0LB_0RB1RA_1LB0RD 4 8
