(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] 0 Z0_1RB0RD_1LC0RC_0RC1LD_1LA0LD /\
  cden (Kp q0 ++ [S0]) [] 0 Z1_1RB0RD_1LC0RC_0RC1LD_1LA0LD = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (KpCounter.cview_some_K p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0RD_1LC0RC_0RC1LD_1LA0LD, cden, Z0_1RB0RD_1LC0RC_0RC1LD_1LA0LD, Z1_1RB0RD_1LC0RC_0RC1LD_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0RD_1LC0RC_0RC1LD_1LA0LD /\
  cden (Kp q0 ++ [S0]) [] j P1_1RB0RD_1LC0RC_0RC1LD_1LA0LD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (KpCounter.cview_some_K p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0RD_1LC0RC_0RC1LD_1LA0LD, cden, P0_1RB0RD_1LC0RC_0RC1LD_1LA0LD, P1_1RB0RD_1LC0RC_0RC1LD_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RD_1LC0RC_0RC1LD_1LA0LD p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RD_1LC0RC_0RC1LD_1LA0LD Z0_1RB0RD_1LC0RC_0RC1LD_1LA0LD Z1_1RB0RD_1LC0RC_0RC1LD_1LA0LD 0 4
               run_z_1RB0RD_1LC0RC_0RC1LD_1LA0LD (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RD_1LC0RC_0RC1LD_1LA0LD P0_1RB0RD_1LC0RC_0RC1LD_1LA0LD P1_1RB0RD_1LC0RC_0RC1LD_1LA0LD 4 8
               run_p_1RB0RD_1LC0RC_0RC1LD_1LA0LD (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (H1 & _).
  unfold Cc_1RB0RD_1LC0RC_0RC1LD_1LA0LD, cden, B0_1RB0RD_1LC0RC_0RC1LD_1LA0LD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC0RC_0RC1LD_1LA0LD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RD_1LC0RC_0RC1LD_1LA0LD
             = (StD, (rep [S0] (S j) ++ [S1], S0, [S1;S1]))).
  { unfold cden, B1_1RB0RD_1LC0RC_0RC1LD_1LA0LD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0] (S j) ++ [S1]) ++ [S0], S0, [S1;S1]))).
  { unfold Cc_1RB0RD_1LC0RC_0RC1LD_1LA0LD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RD_1LC0RC_0RC1LD_1LA0LD. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC0RC_0RC1LD_1LA0LD B0_1RB0RD_1LC0RC_0RC1LD_1LA0LD B1_1RB0RD_1LC0RC_0RC1LD_1LA0LD 4 8 p j' [] []).
    + exact run_ovf_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j' E).
    + exact (geo_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RD_1LC0RC_0RC1LD_1LA0LD : stepn tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RD_1LC0RC_0RC1LD_1LA0LD : existsb (fun tg => cfires tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD c0 7 tg) pins_1RB0RD_1LC0RC_0RC1LD_1LA0LD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_1LC0RC_0RC1LD_1LA0LD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RD_1LC0RC_0RC1LD_1LA0LD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RD_1LC0RC_0RC1LD_1LA0LD : forall t, ~ In t pins_1RB0RD_1LC0RC_0RC1LD_1LA0LD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 2; SRotR 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1; SWin 2; SCycL 3 0; SWin 2; SRotR 1; SWin 1; SCycR 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RD_1LC0RC_0RC1LD_1LA0LD
      with (l := [SWin 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtr_1RB0RD_1LC0RC_0RC1LD_1LA0LD : NonHalt tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD /\ QHBoundTr 32779478 tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD /\ QuasiHaltsTr tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
Proof.
  apply (lap_qh_stage tm_1RB0RD_1LC0RC_0RC1LD_1LA0LD pins_1RB0RD_1LC0RC_0RC1LD_1LA0LD Cc 1 7 32779478).
  - exact bootq_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
  - intros p _. apply lap_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
  - intros t Ht p _. apply fire_1RB0RD_1LC0RC_0RC1LD_1LA0LD. exact Ht.
  - exact wit_1RB0RD_1LC0RC_0RC1LD_1LA0LD.
  - apply qcleb_QC_16. reflexivity.
Qed.

