  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S0;S1] (S j) ++ [S1;S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0RD_1LC0RD_0LB1RA_1LB0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
