             = (StC, (rep [S1;S1] (S j) ++ [S1], S0, [S0;S1]))).
  { unfold cden, B1_1RB0RD_1LC0RD_1LC1RA_0RB0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
