    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC0RD_1LC1RA_0RB0LC B0_1RB0RD_1LC0RD_1LC1RA_0RB0LC B1_1RB0RD_1LC0RD_1LC1RA_0RB0LC 4 14 p j' [] []).
