  - exact bootq_1RB0RD_1LC0RD_1LC1RA_0RB0LC.
  - intros p _. apply lap_1RB0RD_1LC0RD_1LC1RA_0RB0LC.
  - intros t Ht p _. apply fire_1RB0RD_1LC0RD_1LC1RA_0RB0LC. exact Ht.
  - exact wit_1RB0RD_1LC0RD_1LC1RA_0RB0LC.
  - apply qcleb_QC_16. reflexivity.
Qed.

